  UIElement ConnectionRow(ApiConnection entry,bool primary,int index){
   var row=new Grid();row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(26)});row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(118)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});
   if(primary){var dot=T("●",11,"#E8E5DF");dot.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(dot);}else{var enabled=new CheckBox{Tag=entry.Id,IsChecked=entry.Enabled,VerticalAlignment=VerticalAlignment.Center,ToolTip="Utiliser cette clé en secours"};enabled.Checked+=(s,e)=>{SetConnectionEnabled(entry.Id,true);entry.Enabled=true;if(refreshHealth!=null)refreshHealth();};enabled.Unchecked+=(s,e)=>{SetConnectionEnabled(entry.Id,false);entry.Enabled=false;if(refreshHealth!=null)refreshHealth();};row.Children.Add(enabled);}
   var name=T((primary?"Clé principale":entry.Name)+(entry==null?"":" · "+entry.QuotaGroup),14);name.TextWrapping=TextWrapping.NoWrap;name.TextTrimming=TextTrimming.CharacterEllipsis;
   var caption=T(entry==null?"À configurer":entry.QuotaGroup+" · "+(primary?"Principale":"Secours "+(index+1)),11,"#989892");caption.ToolTip=entry==null?null:"Organisation : "+entry.QuotaGroup;caption.TextWrapping=TextWrapping.NoWrap;caption.TextTrimming=TextTrimming.CharacterEllipsis;
   var status=T("",11,"#989892");status.TextWrapping=TextWrapping.NoWrap;status.TextTrimming=TextTrimming.CharacterEllipsis;Action updateStatus=()=>{if(entry==null){status.Text="À configurer";return;}if(!primary&&!entry.Enabled){status.Text="Désactivée";return;}string correction=health.Label(entry.Id,entry.QuotaGroup,entry.Model,DateTime.UtcNow),creative=health.Label(entry.Id,entry.QuotaGroup,OperationRoutes.RephraseModel,DateTime.UtcNow);status.Text=entry.Model==OperationRoutes.RephraseModel?"Tous les usages : "+correction:"Correction : "+correction+" · RP : "+creative;status.Foreground=B(status.Text.Contains("Quota")?"#D4AF78":status.Text.Contains("Erreur")?"#CD897F":status.Text.Contains("Disponible")?"#8EBA9A":"#989892");status.ToolTip="RP : reformulation et génération. État observé lors du dernier appel ; le quota restant n’est pas connu.";};refreshHealth+=updateStatus;updateStatus();var identity=S(name,Space(3),status);identity.VerticalAlignment=VerticalAlignment.Center;identity.Margin=new Thickness(0,0,14,0);identity.ToolTip=entry==null?null:"Compte : "+entry.QuotaGroup;Grid.SetColumn(identity,1);row.Children.Add(identity);
   var suffix=T(ConnectionDisplay.KeySuffix(entry==null?null:entry.Key),12,"#989892");suffix.FontFamily=new FontFamily("Consolas");suffix.VerticalAlignment=VerticalAlignment.Center;suffix.TextWrapping=TextWrapping.NoWrap;Grid.SetColumn(suffix,2);row.Children.Add(suffix);
   var test=SmallButton("Tester",()=>{});test.IsEnabled=entry!=null;test.Click+=async(s,e)=>{if(entry==null||busy||capturing)return;busy=true;host.IsEnabled=false;RefreshGlobalState();ConnectionFeedback("Test en cours…");try{var timer=System.Diagnostics.Stopwatch.StartNew();await api.TestConnection(entry);ConnectionFeedback("Connexion validée · "+(timer.ElapsedMilliseconds/1000.0).ToString("0.00")+" s");}catch(Exception ex){ConnectionFeedback(ex.Message,true);}finally{busy=false;host.IsEnabled=true;RefreshGlobalState();}};Grid.SetColumn(test,3);row.Children.Add(test);
   var more=SmallButton("⋯",()=>{});more.ToolTip="Modifier, réordonner ou supprimer";more.Click+=(s,e)=>{var menu=new ContextMenu();var edit=new MenuItem{Header=entry==null?"Ajouter la clé principale":"Modifier"};edit.Click+=(a,b)=>EditConnection(entry,primary);menu.Items.Add(edit);if(!primary){var up=new MenuItem{Header="Monter",IsEnabled=index>0};up.Click+=(a,b)=>MoveConnection(entry.Id,-1);menu.Items.Add(up);var down=new MenuItem{Header="Descendre",IsEnabled=index<new ConnectionVault(store.Root).Load().Count-1};down.Click+=(a,b)=>MoveConnection(entry.Id,1);menu.Items.Add(down);}if(entry!=null||(primary&&store.HasKey)){menu.Items.Add(new Separator());var remove=new MenuItem{Header="Supprimer"};remove.Click+=(a,b)=>Safe(()=>RemoveConnection(entry,primary));menu.Items.Add(remove);}menu.PlacementTarget=more;menu.IsOpen=true;};Grid.SetColumn(more,4);row.Children.Add(more);
   return new Border{Child=row,Padding=new Thickness(0,8,0,8),BorderBrush=B("#383836"),BorderThickness=new Thickness(0,0,0,1)};
  }
  void SetConnectionEnabled(string id,bool enabled){var vault=new ConnectionVault(store.Root);var list=vault.Load();list.Single(c=>c.Id==id).Enabled=enabled;vault.Save(list);revision++;}
  void MoveConnection(string id,int delta){Safe(()=>{var vault=new ConnectionVault(store.Root);var list=vault.Load();int before=list.FindIndex(c=>c.Id==id),after=before+delta;if(before<0||after<0||after>=list.Count)return;var item=list[before];list.RemoveAt(before);list.Insert(after,item);vault.Save(list);revision++;Render();});}
  void RemoveConnection(ApiConnection entry,bool primary){if(MessageBox.Show(w,"Supprimer cette clé enregistrée ?","Clé API",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;if(primary)store.RemoveKey();else{var vault=new ConnectionVault(store.Root);var list=vault.Load();list.RemoveAll(c=>c.Id==entry.Id);vault.Save(list);}revision++;Header();Render();ConnectionFeedback("Clé supprimée de ce PC.");}
